def transform(g):
 g=[r[:] for r in g]; pts=[(r,c,g[r][c]) for r in range(len(g)) for c in range(len(g[0])) if g[r][c]]
 dirs={1:(0,1),2:(0,-1),3:(1,0),6:(-1,0)}
 for r,c,v in pts:
  if v not in dirs: continue
  dr,dc=dirs[v]; rr,cc=r+dr,c+dc
  while 0<=rr<len(g) and 0<=cc<len(g[0]):
   if g[rr][cc]: break
   g[rr][cc]=5; rr+=dr;cc+=dc
 return g
